{
  "criteria": [
    "自己的解释",
    "可协助部分",
    "人负责部分",
    "验证动作"
  ],
  "assessment": {
    "type": "multiple_choice",
    "questions": [
      {
        "type": "multiple_choice",
        "question": "下面哪种说法最符合本课的 AI 使用原则？",
        "options": [
          {
            "id": "a",
            "label": "回答写得流畅，就可以直接当成事实使用。"
          },
          {
            "id": "b",
            "label": "AI 可以协助产出，但关键方向和事实验证仍由人负责。"
          },
          {
            "id": "c",
            "label": "只要给 AI 一个专家角色，它就会自动避免出错。"
          }
        ],
        "correctOptionId": "b",
        "explanation": "正确。AI 能放大产出效率，但不能替你承担方向判断或事实验证。"
      },
      {
        "question": "根据本课，以下哪一项是核心原则？",
        "options": [
          {
            "id": "a",
            "label": "AI 根据语言和数据中的模式生成内容；流畅不等于正确"
          },
          {
            "id": "b",
            "label": "让 AI 自己决定关键标准，减少人的干预。"
          },
          {
            "id": "c",
            "label": "只要输出足够长，就代表理解已经足够。"
          }
        ],
        "correctOptionId": "a",
        "explanation": "本课的核心原则是：AI 根据语言和数据中的模式生成内容；流畅不等于正确。"
      },
      {
        "question": "完成本课后，你应当具备哪项能力？",
        "options": [
          {
            "id": "a",
            "label": "记住更多 AI 营销术语，不需要实际判断。"
          },
          {
            "id": "b",
            "label": "能用自己的话解释 AI 的工作方式，并区分一个适合交给 AI 的任务和一个必须由人负责的判断。"
          },
          {
            "id": "c",
            "label": "让 AI 替你承担最终结果和责任。"
          }
        ],
        "correctOptionId": "b",
        "explanation": "本课的能力目标是：能用自己的话解释 AI 的工作方式，并区分一个适合交给 AI 的任务和一个必须由人负责的判断。"
      }
    ]
  },
  "translationNotes": [
    "Keep option ids unchanged.",
    "Translate labels/explanations only.",
    "Do not translate code, commands, product names, IDs, JSON keys, or controlled values."
  ]
